#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, time, cost;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int V, N, M;
    cin >> V >> N >> M;

    vector<vector<Edge>> adj(N + 1);

    for (int i = 0; i < M; ++i) {
        int A, B, T, P;
        cin >> A >> B >> T >> P;
        adj[A].push_back({B, T, P});
        adj[B].push_back({A, T, P});
    }

    int X, Y;
    cin >> X >> Y;

    const int INF = 1e9;

    vector<vector<int>> dist(N + 1, vector<int>(V + 1, INF));
    priority_queue<tuple<int, int, int>, vector<tuple<int, int, int>>, greater<tuple<int, int, int>>> pq;

    dist[X][0] = 0;
    pq.push({0, X, 0});

    while (!pq.empty()) {
        auto [d, u, c] = pq.top();
        pq.pop();

        if (d != dist[u][c]) continue;

        for (const Edge &e : adj[u]) {
            int nc = c + e.cost;
            if (nc > V) continue;

            int nd = d + e.time;
            if (nd < dist[e.to][nc]) {
                dist[e.to][nc] = nd;
                pq.push({nd, e.to, nc});
            }
        }
    }

    int ans = INF;
    for (int c = 0; c <= V; ++c) {
        ans = min(ans, dist[Y][c]);
    }

    if (ans == INF) cout << -1 << '\n';
    else cout << ans << '\n';

    return 0;
}
